class Solution:
    def isConvex(self, points: list[list[int]]) -> bool:
        for i, (x, y) in enumerate(points):
            a, b = points[(i + 1) % len(points)]
            sign = 0
            for c, d in points:
                cross = (a - x) * (d - y) - (b - y) * (c - x)
                if cross:
                    current = 1 if cross > 0 else -1
                    if sign and sign != current:
                        return False
                    sign = current
        return True
